interface ProposalRequest {
  intent: string;
  visibleItemIds: string[];
  contextVersion: number;
}

interface ApplyProposalCommand {
  commandId: string;
  proposalId: string;
  basedOnVersion: number;
  selectedItemIds: string[];
  edits: Record<string, string>;
}

interface AIReviewClient {
  requestProposal(input: ProposalRequest, signal: AbortSignal): Promise<AIProposal>;
  refreshProposal(input: { proposalId: string }, signal: AbortSignal): Promise<AIProposal>;
  applyProposal(input: ApplyProposalCommand, signal: AbortSignal): Promise<CommandOutcome>;
  getCommandOutcome(commandId: string, signal: AbortSignal): Promise<CommandOutcome>;
}
